<?php
/** Owner controls on synthetic disposable state only. */
declare(strict_types=1);
if(!defined('TGIT_DISPOSABLE_TEST_SITE')||TGIT_DISPOSABLE_TEST_SITE!==true)throw new RuntimeException('Disposable site required.');

test('Tickerbot controls show complete scoped choices and saved inventory without enrollment or requests',function()use($tracker,$db,$owner,$viewer){
 [$s,$w,$scope,$now]=tbs_context();[$asset,$list]=tbp_seed($s,$w);$foreign=(int)$tracker->create_workspace(['name'=>'Other choices'])['id'];$other=(int)$tracker->create_watchlist($foreign,['name'=>'FOREIGN-CHOICE'],'other-choice')['id'];$before=$s->usage($w);$read=$s->controls($w);equal($read['watchlists'],[['id'=>$list,'name'=>'Capacity scope']]);equal($read['selection']['watchlists'],[$list]);equal($read['inventory']['complete'],true);equal($read['inventory']['projected_monthly_attempts'],372);equal($read['cadence'],['revision'=>0,'enabled'=>false]);equal($s->usage($w),$before);equal(str_contains(json_encode($read),'FOREIGN-CHOICE'),false);$untrusted=new \GainerInteractive\IGTradingJournal\Application\TickerbotStore($db,$viewer,wp_generate_uuid4(),$scope,$now);tbs_denied(fn()=>$untrusted->controls($w));
});
test('Tickerbot recurring review binds settings scope and cadence revisions under lock',function(){
 [$s,$w]=tbs_context();tbp_seed($s,$w);$read=$s->controls($w);$s->configure($w);$conflict=false;try{$s->save_cadence($w,true,0,$read['settings_revision'],$read['selection']['revision']);}catch(UnexpectedValueException $e){$conflict=true;}equal($conflict,true);equal($s->cadence($w),null);$read=$s->controls($w);$s->select_scope($w,[],[],$read['selection']['revision']);$conflict=false;try{$s->save_cadence($w,true,0,$read['settings_revision'],$read['selection']['revision']);}catch(UnexpectedValueException $e){$conflict=true;}equal($conflict,true);$read=$s->controls($w);$s->save_cadence($w,true,0,$read['settings_revision'],$read['selection']['revision']);equal($s->readiness($w)['recurring_review'],'reviewed');equal($s->usage($w)['attempts'],0);equal($s->readiness($w)['latest_run'],null);$s->save_cadence($w,false,1,$read['settings_revision'],$read['selection']['revision']);equal($s->readiness($w)['recurring_review'],'off');
});
test('Tickerbot controls routes save explicit scope and recurring intent without HTTP',function()use($tracker,$db,$owner,$viewer){
 $w=(int)$tracker->create_workspace(['name'=>'Owner controls routes'])['id'];$service=\GainerInteractive\IGTradingJournal\Infrastructure\TickerbotSetup::service($db,$owner,$w,wp_generate_uuid4());$account=$db->row('SELECT monthly_cap FROM '.$db->table('tickerbot_accounts').' WHERE scope_digest=%s',[hash('sha256','tickerbot/account/'.TGIT_TICKERBOT_ACCOUNT_SCOPE)]);$service->configure($w,(int)$account['monthly_cap']);$counted=$service->usage($w)['attempts'];
 $call=function(string $operation,?array $body=null)use($w){$request=new WP_REST_Request($body===null?'GET':'POST','/tgit/v1/workspaces/'.$w.'/tickerbot/controls');$request->set_url_params(['workspace'=>(string)$w]);if($body!==null){$request->set_header('Content-Type','application/json');$request->set_body(json_encode($body));}return \GainerInteractive\IGTradingJournal\Http\Controller::dispatch($request,$operation);};
 wp_set_current_user($owner);$read=$call('tickerbot_controls')->get_data()['data'];equal($read['selection']['revision'],0);$result=$call('tickerbot_scope',['watchlists'=>[],'trades'=>[],'expected_revision'=>0]);equal($result instanceof WP_REST_Response,true);$body=['enabled'=>true,'acknowledged'=>true,'expected_revision'=>0,'expected_settings'=>$read['settings_revision'],'expected_scope'=>1];equal(is_wp_error($call('tickerbot_cadence',array_replace($body,['acknowledged'=>false]))),true);equal(is_wp_error($call('tickerbot_cadence',$body+['account_scope'=>'forged'])),true);equal(is_wp_error($call('tickerbot_scope',['watchlists'=>['1'],'trades'=>[],'expected_revision'=>1])),true);equal($call('tickerbot_cadence',$body) instanceof WP_REST_Response,true);equal(is_wp_error($call('tickerbot_cadence',$body)),true);equal($service->usage($w)['attempts'],$counted);equal($service->readiness($w)['latest_run'],null);wp_set_current_user($viewer);equal(is_wp_error($call('tickerbot_controls')),true);wp_set_current_user($owner);
});

test('Tickerbot owner choices include records beyond the first collection page',function()use($db,$owner){
 [$s,$w]=tbs_context();for($i=0;$i<101;$i++){$id=$db->insert('watchlists',['workspace_id'=>$w,'uuid'=>wp_generate_uuid4(),'name'=>'Choice '.$i,'created_by'=>$owner,'created_at'=>'2026-10-15 12:00:00']);} $read=$s->controls($w);equal(count($read['watchlists']),101);equal($read['watchlists'][100]['id'],$id);equal($read['watchlists'][100]['name'],'Choice 100');equal($s->usage($w)['attempts'],0);
});
